We should now identify the single underlying food concept without a synonym duplicate. A simplistic way is to cluster near-duplicates via fuzzy similarity and then keep only items that have no similar partner. Warning: this is heuristic. We'll use difflib's ratio and a relatively permissive threshold to eliminate potential synonym pairs.

python
import xlrd
from difflib import SequenceMatcher

xls_path = "/Data2/v-weilinjin/workshop/AttributeBench/benchmarks/GAIA/2023/validation/9b54f9d9-35ee-4a14-b62f-d130ea00317f_extracted/food_duplicates.xls"
book = xlrd.open_workbook(xls_path)
sheet = book.sheet_by_index(0)
items = []
for r in range(sheet.nrows):
    for c in range(sheet.ncols):
        v = sheet.cell_value(r,c)
        if isinstance(v,str) and v.strip():
            items.append(v.strip().lower())

# Remove near-duplicates (threshold 0.5) by building groups; very permissive on purpose
n = len(items)
paired = set()
for i in range(n):
    for j in range(i+1, n):
        if SequenceMatcher(None, items[i], items[j]).ratio() >= 0.5:
            paired.add(items[i]); paired.add(items[j])

singletons = sorted(set(items) - paired)
print("Singletons after fuzzy clustering (len=%d):" % len(singletons))
print(singletons[:30])

# Show a few specific pair similarities
def sim(a,b):
    return round(SequenceMatcher(None,a,b).ratio(),2)
examples = [("turtle soup","congee"),("rice porridge","congee"),("java","coffee")]
for a,b in examples:
    print(f"sim({a},{b})=", sim(a,b))
